package com.example.payment.integrationtest.paymentgateway;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import com.sun.net.httpserver.HttpServer;
import java.math.BigDecimal;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.client.RestClient;

/** Runs the real gateway over HTTP against a local stand-in for the provider. */
class HttpPaymentGatewayTest {

    private HttpServer server;
    private HttpPaymentGateway gateway;
    private final AtomicReference<String> method = new AtomicReference<>();
    private final AtomicReference<String> path = new AtomicReference<>();
    private final AtomicReference<String> contentType = new AtomicReference<>();
    private final AtomicReference<String> body = new AtomicReference<>();
    private volatile int status = 200;
    private volatile String responseBody = "{}";

    @BeforeEach
    void startProvider() throws Exception {
        server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        server.createContext("/", exchange -> {
            method.set(exchange.getRequestMethod());
            path.set(exchange.getRequestURI().getPath());
            contentType.set(exchange.getRequestHeaders().getFirst("Content-Type"));
            body.set(new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8));
            var bytes = responseBody.getBytes(StandardCharsets.UTF_8);
            exchange.getResponseHeaders().add("Content-Type", "application/json");
            exchange.sendResponseHeaders(status, bytes.length == 0 ? -1 : bytes.length);
            if (bytes.length > 0) exchange.getResponseBody().write(bytes);
            exchange.close();
        });
        server.start();
        gateway = new HttpPaymentGateway(
                RestClient.builder().baseUrl("http://127.0.0.1:" + server.getAddress().getPort()).build());
    }

    @AfterEach
    void stopProvider() {
        server.stop(0);
    }

    private AuthorizationOutcome authorize() {
        return gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "eur"));
    }

    @Test
    void the_authorization_is_posted_as_json_with_reference_amount_and_currency() throws Exception {
        responseBody = "{\"status\":\"approved\"}";

        authorize();

        assertThat(method.get()).isEqualTo("POST");
        assertThat(path.get()).isEqualTo("/v1/authorizations");
        assertThat(contentType.get()).startsWith("application/json");
        var json = new com.fasterxml.jackson.databind.ObjectMapper().readTree(body.get());
        assertThat(json.fieldNames()).toIterable().containsExactlyInAnyOrder("reference", "amount", "currency");
        assertThat(json.get("reference").asText()).isEqualTo("ORD-7");
        assertThat(json.get("amount").decimalValue()).isEqualByComparingTo("12.50");
        assertThat(json.get("amount").isNumber()).isTrue();
        assertThat(json.get("currency").asText()).isEqualTo("EUR");
    }

    @Test
    void an_approved_answer_is_read_as_approved() {
        responseBody = "{\"status\":\"approved\"}";

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_is_read_as_declined() {
        responseBody = "{\"status\":\"declined\"}";

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_unknown_status_is_never_treated_as_approved() {
        responseBody = "{\"status\":\"pending\"}";

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void additional_fields_in_the_answer_are_tolerated() {
        responseBody = "{\"status\":\"approved\",\"id\":\"auth_1\",\"extra\":{\"a\":1}}";

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_402_refusal_is_a_decline_even_with_an_approved_looking_body() {
        status = 402;
        responseBody = "{\"status\":\"approved\"}";

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_refusal_without_a_body_is_a_decline() {
        status = 402;
        responseBody = "";

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_request_the_provider_rejects_is_reported_as_a_failure_not_a_decline() {
        status = 400;
        responseBody = "{\"error\":\"invalid_request\"}";

        assertThatThrownBy(this::authorize).isInstanceOf(IllegalStateException.class).hasMessageContaining("400");
    }

    @Test
    void a_provider_outage_is_reported_as_a_failure_not_a_decline() {
        status = 503;
        responseBody = "";

        assertThatThrownBy(this::authorize).isInstanceOf(IllegalStateException.class).hasMessageContaining("503");
    }

    @Test
    void an_empty_success_body_is_not_approved() {
        responseBody = "";

        assertThat(authorize()).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_malformed_success_body_fails_loudly_instead_of_approving() {
        responseBody = "not json";

        assertThatThrownBy(this::authorize).isInstanceOf(RuntimeException.class);
    }
}
